package com.ngocdevv.nativecook.blocks.gestures.pinchtosummarize

import androidx.compose.foundation.Canvas
import androidx.compose.runtime.Composable
import androidx.compose.runtime.remember
import androidx.compose.ui.Modifier
import androidx.compose.ui.graphics.Color
import androidx.compose.ui.graphics.drawscope.scale
import androidx.compose.ui.graphics.vector.PathParser
import androidx.compose.ui.geometry.Offset

/** Exact bundled Ionicons outlines; the source package notice is in PinchToSummarizeIcons.LICENSE. */
@Composable
internal fun PtsIonicon(name: String, color: Color, modifier: Modifier = Modifier) {
    val path = remember(name) { PathParser().parsePathString(requireNotNull(ptsIoniconPaths[name])).toPath() }
    Canvas(modifier) {
        scale(size.width / 512f, size.height / 512f, pivot = Offset.Zero) {
            drawPath(path, color)
        }
    }
}

